import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { CURSOR_DICT } from './cursor-pt-dict.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Tradução e Personalização por: Emerson Teles
const home = process.env.USERPROFILE;
const cursorUserData = path.join(home, '.cursor');
const roamingCursor = path.join(home, 'AppData', 'Roaming', 'Cursor');

// 1. Configurar argv.json sem BOM em todos os locais necessarios
const argvLocations = [
  path.join(cursorUserData, 'argv.json'),
  path.join(roamingCursor, 'argv.json'),
  path.join(roamingCursor, 'User', 'argv.json')
];
argvLocations.forEach(p => {
  try {
    fs.mkdirSync(path.dirname(p), { recursive: true });
    let data = { "enable-crash-reporter": true, "locale": "pt-br" };
    if (fs.existsSync(p)) {
      try {
        let raw = fs.readFileSync(p, 'utf8');
        if (raw.charCodeAt(0) === 0xFEFF) raw = raw.slice(1);
        data = { ...JSON.parse(raw), locale: 'pt-br' };
      } catch (e) {}
    }
    fs.writeFileSync(p, JSON.stringify(data, null, 2), 'utf8');
  } catch (e) {}
});
console.log('[+] argv.json configurado com "locale": "pt-br" em todos os locais (sem BOM).');

// 1.0.1 Limpar .obsolete e registrar pacote oficial em extensions.json
const extDirBase = path.join(cursorUserData, 'extensions');
const obsPath = path.join(extDirBase, '.obsolete');
if (fs.existsSync(obsPath)) {
  try {
    let obs = JSON.parse(fs.readFileSync(obsPath, 'utf8'));
    let mod = false;
    for (const k of Object.keys(obs)) {
      if (k.toLowerCase().includes('ms-ceintl') || k.toLowerCase().includes('pt-br')) {
        delete obs[k];
        mod = true;
      }
    }
    if (mod) fs.writeFileSync(obsPath, JSON.stringify(obs, null, 2), 'utf8');
  } catch (e) {}
}

const extJsonPath = path.join(extDirBase, 'extensions.json');
const langFolderName = 'ms-ceintl.vscode-language-pack-pt-br-1.128.0-universal';
const langFullPath = path.join(extDirBase, langFolderName);
if (fs.existsSync(langFullPath)) {
  try {
    let extList = [];
    if (fs.existsSync(extJsonPath)) {
      extList = JSON.parse(fs.readFileSync(extJsonPath, 'utf8'));
    }
    const hasPkg = extList.some(item => 
      item.identifier?.id?.toLowerCase() === 'ms-ceintl.vscode-language-pack-pt-br' ||
      item.relativeLocation === langFolderName
    );
    if (!hasPkg) {
      const fsPathWin = langFullPath.replace(/\//g, '\\');
      const extUri = 'file:///' + langFullPath.replace(/\\/g, '/').replace(/:/g, '%3A');
      const uriPath = '/' + langFullPath.replace(/\\/g, '/');
      extList.push({
        identifier: { id: 'ms-ceintl.vscode-language-pack-pt-br' },
        version: '1.128.0',
        location: {
          $mid: 1,
          fsPath: fsPathWin,
          _sep: 1,
          external: extUri,
          path: uriPath,
          scheme: 'file'
        },
        relativeLocation: langFolderName,
        metadata: {
          isApplicationScoped: true,
          isMachineScoped: false,
          isBuiltin: false,
          installedTimestamp: Date.now(),
          pinned: true,
          source: 'gallery',
          publisherId: 'ms-ceintl',
          publisherDisplayName: 'Microsoft',
          targetPlatform: 'universal',
          updated: true,
          private: false,
          isPreReleaseVersion: false,
          hasPreReleaseVersion: false,
          preRelease: false
        }
      });
      fs.writeFileSync(extJsonPath, JSON.stringify(extList, null, '\t'), 'utf8');
      console.log('[+] ms-ceintl.vscode-language-pack-pt-br registrado em extensions.json.');
    }
  } catch (e) {}
}

// 2. Configurar languagepacks.json
const lpPath = path.join(roamingCursor, 'languagepacks.json');
fs.mkdirSync(roamingCursor, { recursive: true });

const extDir = path.join(cursorUserData, 'extensions', 'ms-ceintl.vscode-language-pack-pt-br-1.128.0-universal');
const mainI18n = path.join(extDir, 'translations', 'main.i18n.json');
const extI18nDir = path.join(extDir, 'translations', 'extensions');

let lp = {};
if (fs.existsSync(lpPath)) {
  try {
    lp = JSON.parse(fs.readFileSync(lpPath, 'utf8'));
  } catch (e) {}
}

const translations = {
  "vscode": mainI18n
};

if (fs.existsSync(extI18nDir)) {
  for (const f of fs.readdirSync(extI18nDir)) {
    if (f.endsWith('.i18n.json')) {
      const extName = f.replace(/\.i18n\.json$/, '');
      translations[extName] = path.join(extI18nDir, f);
    }
  }
}

const chosenHash = lp['pt-br']?.hash || 'e496b3944a02fd0f853a2fb0dfb7c223';
lp['pt-br'] = {
  hash: chosenHash,
  extensions: [],
  translations: translations,
  label: 'português (Brasil)'
};

fs.writeFileSync(lpPath, JSON.stringify(lp), 'utf8');
console.log('[+] AppData/Roaming/Cursor/languagepacks.json configurado.');

