function translate(str) {
  if (!str || typeof str !== 'string') return str;
  if (DICT[str]) return DICT[str];
  const trimmed = str.trim();
  if (DICT[trimmed]) return str.replace(trimmed, DICT[trimmed]);
  if (trimmed.startsWith('&&')) {
    const withoutAmp = trimmed.slice(2);
    if (DICT[withoutAmp]) return '&&' + DICT[withoutAmp];
  }
  return str;
}

// 3. Pré-gerar cache CLP para versões instaladas do Cursor
function findCursorInstallDirs() {
  const candidates = [
    path.join(process.env.LOCALAPPDATA, 'Programs', 'cursor'),
    path.join(process.env.LOCALAPPDATA, 'Programs', 'Cursor'),
    'C:\\Program Files\\cursor',
    'C:\\Program Files\\Cursor'
  ];
  return candidates.filter(c => fs.existsSync(path.join(c, 'resources', 'app', 'product.json')));
}


function patchWorkbench(installDir) {
  try {
    const outDir = path.join(installDir, 'resources', 'app', 'out', 'vs', 'workbench');
    const glassPath = path.join(outDir, 'workbench.glass.main.js');
    const deskPath = path.join(outDir, 'workbench.desktop.main.js');
    const glassCssPath = path.join(outDir, 'workbench.glass.main.css');
    const deskCssPath = path.join(outDir, 'workbench.desktop.main.css');

    const pointerFix = '\n.monaco-workbench .workbench-hover.chat-hover-tooltip,.monaco-workbench .workbench-hover.chat-hover-tooltip *{pointer-events:none!important;}\n';
    for (const cp of [glassCssPath, deskCssPath]) {
      if (fs.existsSync(cp)) {
        let css = fs.readFileSync(cp, 'utf8');
        if (!css.includes('.workbench-hover.chat-hover-tooltip *{pointer-events:none!important;}')) {
          css += pointerFix;
          fs.writeFileSync(cp, css, 'utf8');
        }
      }
    }

    if (fs.existsSync(glassPath)) {
      let g = fs.readFileSync(glassPath, 'utf8');
      g = g.replaceAll('children:"Create new canvas"', 'children:"Criar nova tela"')
           .replaceAll('title:{value:"Add New Custom Docs",original:"Add New Custom Docs"}', 'title:{value:"Adicionar Nova Documentação Personalizada",original:"Add New Custom Docs"}')
           .replaceAll('.LABEL="Add User Rule"', '.LABEL="Adicionar Regra do Usuário"')
           .replaceAll('.title="Add User Rule"', '.title="Adicionar Regra do Usuário"')
           .replaceAll('placeholder="Enter user rule to store\\u2026"', 'placeholder="Digite a regra do usuário para armazenar\\u2026"')
           .replaceAll('prompt="Type the user rule you want to store for future use"', 'prompt="Digite a regra do usuário que você deseja armazenar para uso futuro"')
           .replace('hintText:"Add files"', 'hintText:"Adicionar arquivos"')
           .replace('hintText:"Stop voice recording"', 'hintText:"Parar gravação de voz"')
           .replace('hintText:`Voice Input (${_})`', 'hintText:`Entrada de Voz (${_})`')
           .replace('onMouseEnter:ft=>N()?(Le(ft,`Voice Input (${_})`),!0):!1', 'onMouseEnter:ft=>N()?(Le(ft,`Entrada de Voz (${_})`),!0):!1')
           .replace('hintText:"Stop Agent"', 'hintText:"Parar Agente"')
           .replaceAll('"Authenticating..."', '"Autenticando..."')
           .replace('`Connects Cursor to ${i} through MCP`', '`Conecta o Cursor a ${i} via MCP`')
           .replace('l0p="Provides tools and context through MCP"', 'l0p="Fornece ferramentas e contexto via MCP"')
           .replace('s=`Use the ${t} plugin in one concrete, useful way that shows why it\'s valuable in this workspace.`', 's=`Use o plugin ${t} de uma maneira concreta e útil que mostre por que ele é valioso neste espaço de trabalho.`')
           .replace('nxf="Make me a canvas that "', 'nxf="Crie uma tela que "')
           .replace('c0p={connecting:{full:"Connecting...",compact:"Connecting"}', 'c0p={connecting:{full:"Conectando...",compact:"Conectando"}')
           .replace('LIl="Create Project"', 'LIl="Criar Projeto"')
           .replace('Dtf="Create a focused chat where Agents coordinate work"', 'Dtf="Crie um chat focado onde os Agentes coordenam o trabalho"')
           .replace('Ntf="Create Project"', 'Ntf="Criar Projeto"')
           .replace('Ltf="Project name"', 'Ltf="Nome do projeto"')
           .replace('placeholder:z?"Search remote repos, cloud environments...":B==="workspace"?"Search workspaces...":"Search repos, cloud environments..."', 'placeholder:z?"Pesquisar repositórios remotos, ambientes na nuvem...":B==="workspace"?"Pesquisar espaços de trabalho...":"Pesquisar repositórios, ambientes na nuvem..."')
           .replace('h=`Step ${(u>=0?u:0)+1} of ${n.length}`', 'h=`Etapa ${(u>=0?u:0)+1} de ${n.length}`')
           .replace('placeholder:"SSH Hostname"', 'placeholder:"Nome do host SSH"')
           .replace('children:"Type in a host like user@host or select from SSH config"', 'children:"Digite um host como usuario@host ou selecione da configuração SSH"')
           .replace('{label:"Open SSH Config",onClick:a}', '{label:"Abrir Configuração SSH",onClick:a}')
           .replace('kHg=[{id:"host",label:"Host"},{id:"connecting",label:"Connect"},{id:"folder",label:"Folder"}]', 'kHg=[{id:"host",label:"Host"},{id:"connecting",label:"Conectar"},{id:"folder",label:"Pasta"}]')
           .replace('case"connecting":{p=a?"Connection Failed":"Connecting";break e}case"folder":{p="Select Folder";break e}', 'case"connecting":{p=a?"Falha na Conexão":"Conectando";break e}case"folder":{p="Selecionar Pasta";break e}')
           .replaceAll('title:"Hide Sidebar"', 'title:"Ocultar Barra Lateral"')
           .replaceAll('"aria-label":"Hide Sidebar"', '"aria-label":"Ocultar Barra Lateral"')
           .replaceAll('title:"Show Apps Panel"', 'title:"Mostrar Painel de Aplicativos"')
           .replaceAll('title:"Open Apps Panel"', 'title:"Abrir Painel de Aplicativos"')
           .replaceAll('title:"Hide Apps Panel"', 'title:"Ocultar Painel de Aplicativos"')
           .replaceAll('title:"New Output View"', 'title:"Nova Visualização de Saída"')
           .replaceAll('"No changes to review"', '"Nenhuma alteração para revisar"')
           .replaceAll('"No pending changes to review"', '"Nenhuma alteração pendente para revisar"');
      fs.writeFileSync(glassPath, g, 'utf8');
    }

    if (fs.existsSync(deskPath)) {
      let d = fs.readFileSync(deskPath, 'utf8');
      d = d.replaceAll('children:"Create new canvas"', 'children:"Criar nova tela"')
           .replaceAll('title:{value:"Add New Custom Docs",original:"Add New Custom Docs"}', 'title:{value:"Adicionar Nova Documentação Personalizada",original:"Add New Custom Docs"}')
           .replaceAll('.LABEL="Add User Rule"', '.LABEL="Adicionar Regra do Usuário"')
           .replaceAll('.title="Add User Rule"', '.title="Adicionar Regra do Usuário"')
           .replaceAll('placeholder="Enter user rule to store\\u2026"', 'placeholder="Digite a regra do usuário para armazenar\\u2026"')
           .replaceAll('prompt="Type the user rule you want to store for future use"', 'prompt="Digite a regra do usuário que você deseja armazenar para uso futuro"')
           .replace('hintText:"Add files"', 'hintText:"Adicionar arquivos"')
           .replace('hintText:"Stop voice recording"', 'hintText:"Parar gravação de voz"')
           .replace('hintText:`Voice Input (${S})`', 'hintText:`Entrada de Voz (${S})`')
           .replace('onMouseEnter:yn=>B()?(it(yn,`Voice Input (${S})`),!0):!1', 'onMouseEnter:yn=>B()?(it(yn,`Entrada de Voz (${S})`),!0):!1')
           .replace('hintText:"Stop Agent"', 'hintText:"Parar Agente"')
           .replaceAll('"Authenticating..."', '"Autenticando..."')
           .replace('`Connects Cursor to ${i} through MCP`', '`Conecta o Cursor a ${i} via MCP`')
           .replace('DZu="Provides tools and context through MCP"', 'DZu="Fornece ferramentas e contexto via MCP"')
           .replace('s=`Use the ${t} plugin in one concrete, useful way that shows why it\'s valuable in this workspace.`', 's=`Use o plugin ${t} de uma maneira concreta e útil que mostre por que ele é valioso neste espaço de trabalho.`')
           .replace('MZu={connecting:{full:"Connecting...",compact:"Connecting"}', 'MZu={connecting:{full:"Conectando...",compact:"Conectando"}')
           .replace('openLabel:"Create Project Here"', 'openLabel:"Criar Projeto Aqui"');
      // Interceptação das configurações do VS Code/Cursor (Settings Editor) por Emerson Teles
      const qgtIdx = d.indexOf('for(const[t,n]of qGt)');
      if (qgtIdx !== -1) {
        const retIdx = d.indexOf('return e}', qgtIdx);
        if (retIdx !== -1 && retIdx - qgtIdx < 120) {
          d = d.slice(0, retIdx) + 'return (globalThis.CURSOR_TRANSLATE_SETTING?globalThis.CURSOR_TRANSLATE_SETTING(e):e)}' + d.slice(retIdx + 9);
        }
      }
      const hiOld = 'text:i[g]?i[g]:m';
      const hiNew = 'text:i[g]?i[g]:(globalThis.CURSOR_TRANSLATE_SETTING?globalThis.CURSOR_TRANSLATE_SETTING(m):m)';
      if (d.includes(hiOld)) {
        d = d.replace(hiOld, hiNew);
      }
      fs.writeFileSync(deskPath, d, 'utf8');
    }
  } catch (e) {
    console.warn('[-] Erro ao atualizar workbench:', e.message);
  }
}


function patchInnoUpdater(installDir) {
  try {
    const updaterPath = path.join(installDir, 'tools', 'inno_updater.exe');
    if (!fs.existsSync(updaterPath)) return;

    // Se já estiver traduzido, pula
    let buf = fs.readFileSync(updaterPath);
    if (buf.includes(Buffer.from("Atualização do Cursor - ", "utf8"))) {
      console.log(`[+] Atualizador do Cursor em ${updaterPath} ja esta traduzido.`);
      return;
    }

    // Criar backup original se não existir
    const bakPath = updaterPath + '.bak';
    if (!fs.existsSync(bakPath)) {
      fs.copyFileSync(updaterPath, bakPath);
    }

    // Se houver binário traduzido na pasta tools do pacote, copiar diretamente
    const pkgUpdater = path.join(path.dirname(__dirname), 'tools', 'inno_updater.exe');
    if (fs.existsSync(pkgUpdater)) {
      const pkgBuf = fs.readFileSync(pkgUpdater);
      if (pkgBuf.includes(Buffer.from("Atualização do Cursor - ", "utf8"))) {
        fs.copyFileSync(pkgUpdater, updaterPath);
        console.log(`[+] Atualizador do Cursor (${updaterPath}) atualizado a partir do pacote!`);
        return;
      }
    }

    // Patch dinâmico
    function rawToVa(offset) {
      return 0x400000 + 0x256000 + (offset - 0x254600);
    }

    let b1 = 0x2761b0;
    let b2 = 0x276518;
    let b3 = 0x276d28;

    function alloc(blockNum, str) {
      const b = Buffer.from(str, 'utf8');
      let raw;
      if (blockNum === 1) { raw = b1; b1 += b.length + 1; }
      else if (blockNum === 2) { raw = b2; b2 += b.length + 1; }
      else { raw = b3; b3 += b.length + 1; }
      b.copy(buf, raw);
      buf[raw + b.length] = 0;
      return { raw, va: rawToVa(raw), len: b.length };
    }

    const prefix = alloc(1, "Atualização do Cursor - ");
    const phases = [
      alloc(1, "aguardando processos"),
      alloc(1, "removendo versão anterior"),
      alloc(1, "movendo versão preparada"),
      alloc(1, "finalizando instalação"),
      alloc(1, "promoção concluída"),
      alloc(1, "falha na promoção")
    ];

    const messages = [
      alloc(2, "Aguardando o Cursor fechar…"),
      alloc(2, "Removendo a versão anterior…"),
      alloc(2, "Instalando a nova versão…"),
      alloc(2, "Finalizando a instalação…"),
      alloc(2, "Iniciando o Cursor…"),
      alloc(2, "Não foi possível concluir a atualização do Cursor")
    ];

    const stillUpdating = alloc(3, "Ainda atualizando o Cursor…");
    const updated = alloc(3, "Cursor atualizado");
    const titleComplete = alloc(3, "Atualização do Cursor - concluída");
    const titleMismatch = alloc(3, "Atualização do Cursor - versão incompatível");
    const titleWaiting = alloc(3, "Atualização do Cursor - aguardando processo");

    buf.writeUInt32LE(prefix.va, 0x284cc8);
    buf.writeUInt32LE(prefix.len, 0x284ccc);

    for (let i = 0; i < phases.length; i++) {
      buf.writeUInt32LE(phases[i].va, 0x2850a4 + i * 4);
      buf.writeUInt32LE(phases[i].len, 0x2850bc + i * 4);
    }

    for (let i = 0; i < messages.length; i++) {
      buf.writeUInt32LE(messages[i].va, 0x2850d4 + i * 4);
      buf.writeUInt32LE(messages[i].len, 0x2850ec + i * 4);
    }

    buf.writeUInt32LE(stillUpdating.va, 0x7970b);
    buf.writeUInt32LE(stillUpdating.va + stillUpdating.len, 0x796f8);

    buf.writeUInt32LE(titleComplete.va, 0x7a1cc);
    buf.writeUInt32LE(updated.va, 0x7a1e1);
    buf.writeUInt32LE(titleMismatch.va, 0x78606);
    if (buf.readUInt32LE(0x7a23c) === 0x686586) {
      buf.writeUInt32LE(titleMismatch.va, 0x7a23c);
    }
    buf.writeUInt32LE(titleWaiting.va, 0x78619);

    fs.writeFileSync(updaterPath, buf);
    console.log(`[+] Atualizador do Cursor (${updaterPath}) traduzido com sucesso para PT-BR!`);
  } catch (err) {
    console.warn('[-] Erro ao traduzir inno_updater.exe:', err.message);
  }
}

for (const installDir of findCursorInstallDirs()) {
  // patchWorkbench e patchInnoUpdater são gerenciados de forma isolada e segura pelo patch-workbench.js e instalador principal
  try {
    const gitNlsFile = path.join(installDir, 'resources', 'app', 'extensions', 'git', 'package.nls.json');
    if (fs.existsSync(gitNlsFile)) {
      let gNls = fs.readFileSync(gitNlsFile, 'utf8');
      const o = 'To learn more about how to use Git and source control in VS Code [read our docs](https://aka.ms/vscode-scm).';
      const n = 'Para saber mais sobre como usar o Git e o controle do código-fonte no VS Code [leia nossos documentos](https://aka.ms/vscode-scm).';
      if (gNls.includes(o)) {
        gNls = gNls.replaceAll(o, n);
        fs.writeFileSync(gitNlsFile, gNls, 'utf8');
      }
      const gitNlsPt = path.join(installDir, 'resources', 'app', 'extensions', 'git', 'package.nls.pt-br.json');
      fs.writeFileSync(gitNlsPt, gNls, 'utf8');
    }

    const prodFile = path.join(installDir, 'resources', 'app', 'product.json');
    let prodRaw = fs.readFileSync(prodFile, 'utf8');
    if (prodRaw.charCodeAt(0) === 0xFEFF) prodRaw = prodRaw.slice(1);
    const prod = JSON.parse(prodRaw);
    const commit = prod.commit;
    const nlsDir = path.join(installDir, 'resources', 'app', 'out');

    if (commit && fs.existsSync(mainI18n)) {
      const hash = lp['pt-br'].hash;
      const d = `${hash}.pt-br`;
      const u = path.join(roamingCursor, 'clp', d);
      const m = path.join(u, commit);
      const h = path.join(m, 'nls.messages.json');
      const tcf = path.join(u, 'tcf.json');

      fs.mkdirSync(m, { recursive: true });

      let rawKeys = fs.readFileSync(path.join(nlsDir, 'nls.keys.json'), 'utf8');
      if (rawKeys.charCodeAt(0) === 0xFEFF) rawKeys = rawKeys.slice(1);
      const T = JSON.parse(rawKeys);

      let rawMsgs = fs.readFileSync(path.join(nlsDir, 'nls.messages.json'), 'utf8');
      if (rawMsgs.charCodeAt(0) === 0xFEFF) rawMsgs = rawMsgs.slice(1);
      const S = JSON.parse(rawMsgs);
      const msgsList = Array.isArray(S) ? S : (S.value || []);

      let rawMain = fs.readFileSync(mainI18n, 'utf8');
      if (rawMain.charCodeAt(0) === 0xFEFF) rawMain = rawMain.slice(1);
      const E = JSON.parse(rawMain);

      const C = [];
      let W = 0;
      let translatedViaDict = 0;
      for (const [x, V] of T) {
        const L = E.contents?.[x];
        for (const q of V) {
          const original = msgsList[W];
          let trans = L?.[q];
          if (!trans) {
            trans = translate(original);
            if (trans !== original) translatedViaDict++;
          }
          // Assegurar regra aplicativo / aplicativos
          if (typeof trans === 'string') {
            trans = trans
              .replace(/\bApps\b/g, 'Aplicativos')
              .replace(/\bapps\b/g, 'aplicativos')
              .replace(/\bApp\b/g, 'Aplicativo')
              .replace(/\bapp\b/g, 'aplicativo');
          }
          C.push(trans || original);
          W++;
        }
      }

      const candidateHashes = [lp['pt-br']?.hash, 'e496b3944a02fd0f853a2fb0dfb7c223', '0a47be3009427495c5bac2f12920834a'].filter(Boolean);
      const uniqueHashes = [...new Set(candidateHashes)];
      for (const hash of uniqueHashes) {
        const d = `${hash}.pt-br`;
        const u = path.join(roamingCursor, 'clp', d);
        const m = path.join(u, commit);
        const h = path.join(m, 'nls.messages.json');
        const tcf = path.join(u, 'tcf.json');

        fs.mkdirSync(m, { recursive: true });
        fs.writeFileSync(h, JSON.stringify(C), 'utf8');
        fs.writeFileSync(tcf, JSON.stringify(lp['pt-br'].translations), 'utf8');
      }
      console.log(`[+] Cache CLP gerado com sucesso para o commit ${commit}! (${W} mensagens, ${translatedViaDict} via dicionário Emerson Teles)`);
    }
  } catch (err) {
    console.warn(`[-] Aviso ao compilar cache para ${installDir}:`, err.message);
  }
}
